$defaults = json_decode('{"navHome":"Accueil","navCircuits":"Nos circuits","navAbout":"Esprit MIARADI","navFaq":"FAQ","navQuote":"Préparer mon voyage","navQuoteButton":"Imaginons votre voyage","heroEyebrow":"NOTRE HISTOIRE · NOTRE PHILOSOPHIE","heroTitle":"Voyageons ensemble,","heroAccent":"partageons l’essentiel.","heroText":"Rencontrer Madagascar autrement, avec celles et ceux qui le font vivre.","heroButton":"Imaginons votre voyage","sofiaEyebrow":"NOUVEAU VOYAGE SIGNATURE","sofiaTitle":"Nord – Nord-Ouest :","sofiaAccent":"au fil du fleuve Sofia","sofiaText":"19 jours entre les paysages du Boeny, les rencontres riveraines, les Tsingy du Nord et les îles de Nosy Be.","sofiaButton":"Découvrir le circuit","sofiaLink":"circuit-nord-nord-ouest.html","sofiaImage":"https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A9lestine-Vall%C3%A9e_de_la_Sofia_(Madagascar).jpg?width=1800","sofiaImageAlt":"Paysage du fleuve Sofia dans le nord-ouest de Madagascar","storyEyebrow":"À PROPOS DE MIARADI","storyTitle":"Voyageons ensemble,","storyAccent":"partageons l’essentiel.","storyLead":"MIARADI est un tour-opérateur réceptif local créé en 2024, né d’une conviction simple : le voyage prend tout son sens lorsqu’il se vit ensemble et se partage.","storyP1":"En malgache, MIARADI évoque l’idée de faire route ensemble, de voyager ensemble, de travailler ensemble et de partager une même vision. C’est cette philosophie qui guide notre démarche et donne une âme à chacun de nos voyages.","storyP2":"Passionnés par Madagascar, nous souhaitons faire découvrir une île aux mille visages, bien au-delà des itinéraires classiques. Nous aimons emmener les voyageurs à la rencontre des régions reculées, des paysages préservés, d’une biodiversité exceptionnelle, des traditions vivantes et des femmes et des hommes qui font la richesse de notre pays.","storyP3":"Avec MIARADI, voyager, c’est prendre le temps de découvrir, d’échanger, de comprendre et de vivre des expériences authentiques. C’est aller à la rencontre d’un Madagascar humain, culturel et naturel, où chaque étape devient une occasion de partage et chaque rencontre, un souvenir précieux.","engagementEyebrow":"NOTRE ENGAGEMENT","engagementTitle":"Une autre façon de concevoir","engagementAccent":"le tourisme.","engagementP1":"Chez MIARADI, nous sommes convaincus que le tourisme peut être une véritable source d’opportunités pour les communautés locales. C’est pourquoi nous construisons nos voyages en collaboration avec des acteurs locaux qui partagent notre vision et notre engagement.","engagementStrong":"Nous ne considérons pas ces femmes et ces hommes comme de simples prestataires ou employés, mais comme de véritables partenaires, porteurs de savoir-faire, de connaissances et de traditions indispensables à la richesse de nos expériences.","engagementP2":"Guides locaux, chauffeurs-accompagnateurs, pisteurs, porteurs, cuisiniers, piroguiers, associations communautaires, gîtes ruraux, artisans… Chacun contribue, à sa manière, à faire vivre le voyage et à créer des retombées positives pour les familles et les territoires concernés.","engagementP3":"Cette approche humaine et collaborative est au cœur de notre stratégie de développement : créer ensemble des expériences singulières, valoriser les ressources locales et faire du voyage une aventure qui profite aussi à celles et ceux qui accueillent les voyageurs.","teamEyebrow":"UNE FORCE COLLECTIVE","teamTitle":"Une équipe, un réseau,","teamAccent":"une même vision.","teamSize":"5","teamSizeLabel":"personnes dans l’équipe","partnerCount":"~40","partnerCountLabel":"collaborateurs et partenaires locaux","teamP1":"MIARADI, c’est avant tout une équipe de 5 personnes passionnées par le voyage et par Madagascar, animées par l’envie de partager les trésors de leur pays avec des voyageurs curieux, respectueux et désireux de vivre autre chose.","teamP2":"Autour de cette équipe, près de 40 collaborateurs et partenaires locaux, répartis dans différentes régions de Madagascar, contribuent à la préparation et à la réalisation de nos circuits. Grâce à leur connaissance du terrain, leur expérience et leur attachement à leur région, ils nous permettent de proposer des voyages au plus près des réalités locales.","teamP3":"Ensemble, nous formons un réseau fondé sur la confiance, la complémentarité et le partage.","closingText":"MIARADI, c’est notre façon de voyager : découvrir Madagascar autrement, rencontrer ceux qui le font vivre et partager bien plus qu’un itinéraire. C’est faire de chaque voyage une aventure humaine, construite ensemble et vécue pleinement.","closingLink":"Parlons de votre voyage","visionEyebrow":"NOTRE VISION DU TOURISME","visionTitle":"Découvrir autrement.","visionAccent":"Partager pleinement.","visionText":"Un voyage MIARADI ne se résume pas aux lieux traversés. Il se construit avec les personnes rencontrées, les cultures découvertes et les territoires qui nous accueillent.","pillar1Title":"Rencontres humaines","pillar1Text":"Prendre le temps d’échanger avec celles et ceux qui partagent leur quotidien, leur histoire et leur savoir-faire.","pillar2Title":"Richesses naturelles et culturelles","pillar2Text":"Explorer la diversité de Madagascar, de ses paysages à ses traditions vivantes, au-delà des itinéraires attendus.","pillar3Title":"Voyage construit ensemble","pillar3Text":"Préparer les circuits avec les partenaires locaux et reconnaître la place essentielle de leur expérience du terrain.","visionCaption":"Madagascar autrement : des paysages, des cultures et des rencontres qui donnent du sens au voyage.","networkEyebrow":"UNE FORCE COLLECTIVE","networkTitle":"Un réseau local au cœur de chaque","networkAccent":"itinéraire.","networkP1":"Notre équipe de 5 personnes travaille avec près de 40 collaborateurs et partenaires locaux : guides, chauffeurs-accompagnateurs, pisteurs, porteurs, cuisiniers, piroguiers, hébergeurs, artisans et associations communautaires.","networkP2":"Leur connaissance du terrain aide à concevoir des étapes cohérentes avec les réalités locales et à proposer des expériences qui vont au-delà d’une simple visite.","networkStrong":"Nous ne les considérons pas comme de simples prestataires, mais comme de véritables partenaires.","networkLink":"Construisons votre voyage ensemble","faqEyebrow":"FAQ · FOIRE AUX QUESTIONS","faqTitle":"Mieux connaître","faqAccent":"MIARADI.","faqIntro":"Notre philosophie, nos partenaires et la manière de préparer votre voyage à Madagascar.","faqLink":"Une autre question ? Parlons-en","faq1Q":"Qu’est-ce que MIARADI ?","faq1A":"MIARADI est un tour-opérateur réceptif local créé en 2024, spécialisé dans la découverte de Madagascar. Nous concevons des voyages authentiques qui permettent d’explorer les paysages, les cultures et les régions du pays tout en favorisant les rencontres et le partage avec les communautés locales.","faq2Q":"Que signifie le nom MIARADI ?","faq2A":"MIARADI évoque l’idée de voyager ensemble, d’avancer ensemble et de partager une même aventure. Ce nom reflète notre philosophie : le voyage est plus enrichissant lorsqu’il rapproche les personnes, valorise les rencontres et se construit collectivement.","faq3Q":"Qu’est-ce qui différencie MIARADI des autres tour-opérateurs ?","faq3A":"Nous privilégions une approche humaine et collaborative du tourisme. Au-delà des sites incontournables, nous souhaitons faire découvrir un Madagascar authentique, notamment ses régions reculées, ses traditions vivantes et ses richesses naturelles, grâce à ceux qui connaissent et font vivre ces territoires.","faq4Q":"Comment MIARADI travaille-t-il avec les communautés locales ?","faq4A":"Nous construisons nos circuits avec des partenaires locaux qui contribuent directement à l’organisation et au déroulement des voyages. Guides, chauffeurs-accompagnateurs, pisteurs, porteurs, cuisiniers, piroguiers, artisans et hébergeurs participent à la création d’expériences enrichissantes et à la valorisation des savoir-faire locaux.","faq5Q":"Les communautés locales sont-elles de simples prestataires ?","faq5A":"Non. Chez MIARADI, nous considérons nos partenaires locaux comme des acteurs essentiels de chaque voyage. Leur expérience, leurs connaissances et leurs traditions contribuent pleinement à la qualité des expériences proposées. Nous privilégions une collaboration fondée sur la confiance, le respect et le partage.","faq6Q":"Quel type de voyage peut-on vivre avec MIARADI ?","faq6A":"Nous proposons une découverte de Madagascar qui associe nature, culture, aventure et rencontres humaines. Nos voyages peuvent conduire les voyageurs vers des paysages préservés, des villages, des sites remarquables et des régions moins fréquentées, selon le circuit choisi.","faq7Q":"Qui compose l’équipe MIARADI ?","faq7A":"MIARADI s’appuie sur une équipe de 5 personnes passionnées par Madagascar et le voyage. Elle travaille avec un réseau de près de 40 collaborateurs et partenaires locaux répartis dans différentes régions du pays. Cette organisation nous permet de nous appuyer sur une connaissance concrète du terrain.","faq8Q":"Quelles sont les valeurs de MIARADI ?","faq8A":"Nos engagements reposent sur cinq valeurs essentielles : le partage, l’authenticité, la collaboration, le respect et la confiance. Elles guident notre façon de construire les voyages et de travailler avec les voyageurs et les partenaires locaux.","metaTitle":"À propos de MIARADI — Voyageons ensemble","metaDescription":"Découvrez l’histoire de MIARADI, notre philosophie du voyage partagé et notre réseau local à Madagascar.","faq8Value1":"Le partage : vivre des expériences qui rapprochent les voyageurs et les habitants.","faq8Value2":"L’authenticité : découvrir Madagascar au-delà des itinéraires classiques.","faq8Value3":"La collaboration : construire nos voyages avec les acteurs locaux.","faq8Value4":"Le respect : valoriser les cultures, les traditions et les territoires visités.","faq8Value5":"La confiance : développer des relations durables avec nos partenaires et nos voyageurs.","faq9Q":"MIARADI privilégie-t-il un tourisme responsable ?","faq9A":"Nous souhaitons développer un tourisme plus humain, attentif aux territoires visités et aux personnes qui les font vivre. Notre démarche consiste notamment à collaborer avec des acteurs locaux, à valoriser leurs compétences et à favoriser des retombées positives pour les communautés. Nous considérons cette approche comme un engagement à faire progresser durablement.","faq10Q":"Pourquoi choisir MIARADI pour découvrir Madagascar ?","faq10A":"Choisir MIARADI, c’est privilégier une découverte de Madagascar fondée sur les rencontres, le partage et la connaissance du terrain. C’est aussi voyager avec une équipe locale qui souhaite faire de chaque circuit une expérience humaine, enrichissante et construite avec ses partenaires.","faq11Q":"Comment préparer un voyage avec MIARADI ?","faq11A":"Découvrez nos circuits pour choisir un voyage adapté à vos envies, à vos centres d’intérêt et à la durée de votre séjour. Vous pouvez ensuite nous contacter pour demander un devis personnalisé et échanger avec notre équipe sur votre projet.","faq12Q":"Quelle est la philosophie de MIARADI en une phrase ?","faq12A":"Voyager ensemble, découvrir autrement et partager l’essentiel. Pour MIARADI, un voyage ne se résume pas aux lieux visités : il se construit aussi à travers les rencontres, les échanges et les liens créés tout au long du parcours.","ctaEyebrow":"LA SUITE S’ÉCRIT ENSEMBLE","ctaTitle":"Et si nous imaginions","ctaAccent":"votre voyage ?","ctaButton":"Parlons de votre projet","footerTagline":"MIARADI — Voyageons ensemble, partageons l’essentiel.","footerHome":"Accueil","footerCircuits":"Nos circuits","footerContact":"Contact","footerFaq":"FAQ","footerBackTop":"Retour en haut ↑","heroImage":"https://commons.wikimedia.org/wiki/Special:FilePath/Walking_the_Avenue_of_the_Baobabs.jpg?width=1800","heroImageAlt":"Allée des baobabs à Madagascar","visionImage":"https://commons.wikimedia.org/wiki/Special:FilePath/Walking_the_Avenue_of_the_Baobabs.jpg?width=1600","visionImageAlt":"Allée des baobabs, paysage emblématique de Madagascar"}', true, 512, JSON_THROW_ON_ERROR);
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET') {
    try {
        $stmt = database_connection()->prepare("SELECT content_json FROM miaradi_page_content WHERE content_key = 'about_page' LIMIT 1");
        $stmt->execute();
        $stored = $stmt->fetchColumn();
        if (is_string($stored) && $stored !== '') {
            $saved = json_decode($stored, true);
            if (is_array($saved)) $defaults = array_merge($defaults, array_intersect_key($saved, $defaults));
        }
        api_json(['data' => $defaults]);
    } catch (Throwable $e) {
        error_log('[miaradi-api] About settings read failed: '.$e->getMessage());
        api_json(['data' => $defaults, 'warning' => 'migration_required']);
    }
}
api_require_admin(); api_method('PUT'); api_require_csrf(); $input = api_read_json(); $data = [];
$imageKeys = ['heroImage','visionImage','sofiaImage'];
foreach ($defaults as $key => $default) {
    $max = str_ends_with($key, 'Alt') ? 250 : (in_array($key, $imageKeys, true) ? 1000 : 2000);
    $value = $input[$key] ?? $default;
    if (!is_string($value)) $value = (string)$default;
    $value = trim($value);
    if (mb_strlen($value, 'UTF-8') > $max) api_json(['error'=>['code'=>'field_too_long','message'=>'Un champ dépasse la longueur autorisée : '.$key]], 422);
    if (in_array($key, $imageKeys, true) && $value !== '' && !preg_match('~^(https?://|assets/|backend/public/uploads/)~i', $value)) api_json(['error'=>['code'=>'invalid_image_path','message'=>'Chemin d’image invalide : '.$key]], 422);
    $data[$key] = $value;
}
try {
    $stmt = database_connection()->prepare("INSERT INTO miaradi_page_content (content_key, content_json) VALUES ('about_page', :content) ON DUPLICATE KEY UPDATE content_json = VALUES(content_json)");
    $stmt->execute(['content' => json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR)]);
    api_json(['data'=>$data,'message'=>'Contenu de la page À propos enregistré.']);
} catch (Throwable $e) {
    error_log('[miaradi-api] About settings save failed: '.$e->getMessage());
    api_json(['error'=>['code'=>'about_save_failed','message'=>'Impossible d’enregistrer le contenu. Vérifiez la connexion à la base de données.']], 503);
}
